// Everything under home/, bundled at build time and keyed by path relative to home/
// (generated by the home-content plugin in vite.config.js):
//   pages:    { 'a/b.md': '# ...' }
//   roadmaps: { 'a/oracle.roadmap.json': { title, nodes, edges } }
import { pages, roadmaps } from 'virtual:home-content'

export { pages, roadmaps }

export const ROADMAP_EXT = '.roadmap.json'

// A roadmap is served at its file path without the extension: a/oracle.roadmap.json -> a/oracle
export const roadmapRoute = (file) => file.slice(0, -ROADMAP_EXT.length)
export const roadmapByRoute = Object.fromEntries(Object.keys(roadmaps).map((f) => [roadmapRoute(f), f]))

export const BASE = import.meta.env.BASE_URL

export function currentPath() {
  let p = window.location.pathname
  try {
    p = decodeURIComponent(p)
  } catch {
    // Malformed escapes (e.g. a stray %): keep the raw path, it simply won't match a page
  }
  if (p.startsWith(BASE)) p = p.slice(BASE.length)
  return p.replace(/^\/+|\/+$/g, '')
}

export const href = (p) => BASE + p.split('/').map(encodeURIComponent).join('/')

// Path inside home/ that a relative link in a markdown file points to, or null for
// absolute, external and anchor links
export function resolvePath(link, filePath) {
  if (!link || /^([a-z]+:|#|\/)/i.test(link)) return null
  const parts = filePath.split('/').slice(0, -1)
  for (const seg of link.split('/')) {
    if (seg === '..') parts.pop()
    else if (seg !== '.' && seg !== '') parts.push(seg)
  }
  return parts.join('/')
}

// Files under home/ that aren't pages (images, PDFs...) are published as they are at /home/<path>
export const assetUrl = (p) => href(`home/${p}`)
const isAsset = (p) => /\.[a-z0-9]+$/i.test(p) && !p.endsWith('.md')

// Resolve relative links inside a markdown file against that file's folder
export function resolveLink(link, filePath) {
  const [target, hash = ''] = splitHash(resolvePath(link, filePath))
  if (target === null) return link
  return (isAsset(target) ? assetUrl(target) : href(target)) + hash
}

// "a/b.md#sezione" -> ["a/b.md", "#sezione"]
function splitHash(p) {
  if (p === null) return [null]
  const i = p.indexOf('#')
  return i < 0 ? [p] : [p.slice(0, i), p.slice(i)]
}

// Page a relative link points to, without its #anchor, or null
export const linkedPage = (link, filePath) => splitHash(resolvePath(link, filePath))[0]

const allFiles = [...Object.keys(pages), ...Object.keys(roadmaps)]

export const isFolder = (path) => path === '' || allFiles.some((p) => p.startsWith(path + '/'))

// Direct children of a folder, '' being the home/ root
export function listFolder(folder) {
  const prefix = folder ? folder + '/' : ''
  const folders = new Set()
  const files = []
  const maps = []
  for (const p of allFiles) {
    if (!p.startsWith(prefix)) continue
    const [head, ...rest] = p.slice(prefix.length).split('/')
    if (rest.length) folders.add(head)
    else if (p.endsWith(ROADMAP_EXT)) maps.push(p)
    else files.push(head)
  }
  return { folders: [...folders].sort(), files: files.sort(), roadmaps: maps.sort() }
}
